const data = $input.first().json.body || $input.first().json;
const login = $env.FABRIKANT_LOGIN || '';
const password = $env.FABRIKANT_PASSWORD || '';

if (!login || !password) {
  return [{ json: {
    publicationId: data.publication_id,
    hasCredentials: false,
    error: 'Не настроены учётные данные Фабрикант — задайте переменные FABRIKANT_LOGIN и FABRIKANT_PASSWORD в docker-compose',
  }}];
}

function escXml(s) {
  return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function fmtDT(d) {
  const pad = n => String(n).padStart(2,'0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}+03:00`;
}

const now = new Date();
const startDT = new Date(now.getTime() + 60 * 60 * 1000);
const endDT = data.execution_term
  ? new Date(data.execution_term)
  : new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
const determinationDT = new Date(endDT.getTime() + 24 * 60 * 60 * 1000);
const summingDT = new Date(endDT.getTime() + 2 * 24 * 60 * 60 * 1000);

const purchaseId = escXml(data.registry_number || String(data.purchase_id));
const subject = escXml(data.subject || ('Закупка ' + purchaseId));
const nmck = Number(data.nmck) || 0;

const items = (data.items || []).filter(i => i.item_name);
const lotItemsXml = items.map((item, idx) => {
  const name = escXml(item.item_name);
  const unit = escXml(item.unit || 'шт');
  const qty = Number(item.quantity) || 1;
  const unitPrice = Number(item.unit_price) || 0;
  const totalPrice = Number(item.total_price) || (unitPrice * qty);
  return `<lotItem><ordinalNumber>${idx+1}</ordinalNumber><positionName>${name}</positionName><okei><code>796</code><name>${unit}</name></okei><qty>${qty}</qty>${unitPrice > 0 ? `<positionPricePerUnit><price>${unitPrice}</price><ndsType>not_payer_nds</ndsType></positionPricePerUnit><positionPrice><price>${totalPrice}</price><ndsType>not_payer_nds</ndsType></positionPrice>` : ''}</lotItem>`;
}).join('');

const deliveryAddress = escXml(data.delivery_address || 'Москва');

const soapXml = `<?xml version="1.0" encoding="UTF-8"?><soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><purchaseNoticeZPCommercial xmlns="http://commercial_trade.multiintegration.common.api.fabrikant.ru/"><body><item><purchaseNoticeZPCommercialData><purchaseId>${purchaseId}</purchaseId><purchaseCategoryCustom>Запрос предложений</purchaseCategoryCustom><name>${subject}</name><notDishonest>false</notDishonest><lots><lot><lotId>${purchaseId}</lotId><subject>${subject}</subject><currency><code>RUB</code></currency><initialSumInfo><initialSum>${nmck}</initialSum><ndsType>not_payer_nds</ndsType></initialSumInfo><deliveryPlace><state>Москва</state><address>${deliveryAddress}</address></deliveryPlace><applicationSupplyNeeded>false</applicationSupplyNeeded>${lotItemsXml ? `<lotItems>${lotItemsXml}</lotItems>` : ''}<proposalStartDateTime>${fmtDT(startDT)}</proposalStartDateTime><proposalEndDateTime>${fmtDT(endDT)}</proposalEndDateTime><proposalDeterminationDateTime>${fmtDT(determinationDT)}</proposalDeterminationDateTime><summingUpDateTime>${fmtDT(summingDT)}</summingUpDateTime><lotFramework>false</lotFramework></lot></lots></purchaseNoticeZPCommercialData></item></body></purchaseNoticeZPCommercial></soap:Body></soap:Envelope>`;

const auth = Buffer.from(`${login}:${password}`).toString('base64');

return [{ json: {
  publicationId: data.publication_id,
  hasCredentials: true,
  soapXml,
  authHeader: `Basic ${auth}`,
}}];

const prev = $input.first().json;
const pubId = prev.publicationId;
const responseText = String(prev.data || prev.body || prev || '');

// Check for successful requestId
const reqIdMatch = responseText.match(/<requestId>([^<]+)<\/requestId>/);
if (reqIdMatch) {
  return [{ json: { publicationId: pubId, success: true, requestId: reqIdMatch[1] }}];
}

// Check for SOAP Fault
const faultMatch = responseText.match(/<faultstring[^>]*>([^<]+)<\/faultstring>/);
const errorText = faultMatch ? faultMatch[1] : ('Неизвестная ошибка Фабрикант. Ответ: ' + responseText.substring(0, 200));

return [{ json: { publicationId: pubId, success: false, error: errorText }}];

const prev = $input.first().json;
return [{ json: {
  publicationId: prev.publicationId,
  callbackBody: {
    status: 'published',
    external_id: prev.requestId,
    external_url: 'https://www.fabrikant.ru/trades/commercial/?id=' + prev.requestId,
  }
}}];

const prev = $input.first().json;
return [{ json: {
  publicationId: prev.publicationId,
  callbackBody: {
    status: 'error',
    error_text: 'Ошибка Фабрикант API: ' + (prev.error || 'Неизвестная ошибка'),
  }
}}];

const prev = $input.first().json;
return [{ json: {
  publicationId: prev.publicationId,
  callbackBody: {
    status: 'error',
    error_text: prev.error || 'Не настроены учётные данные Фабрикант — задайте FABRIKANT_LOGIN и FABRIKANT_PASSWORD в docker-compose',
  }
}}];
